<?php
/** Slice 5 — the upload and import, resolution and day parts, the JSON shapes (pos.md "Proof"). Bea drops the Toast export at Downtown; the admin a generic file at Airport. */
require __DIR__ . '/lib.php';
require_once dirname(__DIR__, 3) . '/app/features/pos/connectors/Xlsx.php';
pos_world();
$bea = at(28, DOWNTOWN);
$ann = at(29, DOWNTOWN);
$marco = at(27, DOWNTOWN);
$admin = at(1, DOWNTOWN);
$since = last_activity_id();
$toast = source_id('SMOKE Toast export');
$square = source_id('SMOKE Square');
$TOAST = FIX . '/toast_items.csv';
$tmp = state_dir() . '/samples';
@mkdir($tmp, 0777, true);

echo "1. The screen\n";
$r = page($bea, '/sales/upload');
ok($r['code'] === 200 && has($r, 'id="upload-form-field-source"') && has($r, 'SMOKE Toast export') && has($r, 'SMOKE SFTP') && !has($r, '>SMOKE Square<'), 'Bea opens the upload: the file sources offered, not Square');
ok(has($r, 'id="upload-form-field-file"') && has($r, 'id="upload-form-field-mapping"') && has($r, 'id="upload-preview-btn"'), 'the file, the mapping, Preview');
$r = page($bea, '/sales/upload?source=' . $toast);
ok($r['code'] === 200 && preg_match('/<option value="' . $toast . '"[^>]*selected/', $r['body']) === 1, '?source= preselects the source');
ok(page($ann, '/sales/upload')['code'] === 403, 'Ann (Viewer) cannot upload: 403');

echo "2. Preview — nothing written\n";
$r = post_file_json($bea, '/sales/upload', ['source' => (string) $toast, 'preview' => 'yes'], 'file', $TOAST);
$p = $r['json']['preview'] ?? [];
ok($r['code'] === 200 && ($p['mapping_key'] ?? '') === 'toast_items' && ($p['checks'] ?? 0) === 5 && ($p['lines'] ?? 0) === 8, "the preview through the source's mapping toast_items: five checks, eight lines");
ok(count($p['preview'] ?? []) === 8 && ($p['preview'][0]['external_id'] ?? '') === 'SMK-001' && ($p['preview'][0]['modifiers'] ?? []) === ['XCHK'], 'every readable row shown (eight — the fixture has eight and a malformed one), SMK-001 with XCHK');
ok(($p['dates'] ?? []) === [['date' => D1, 'lines' => 6, 'run' => null, 'run_no' => null], ['date' => D2, 'lines' => 2, 'run' => null, 'run_no' => null]], 'two dates seen with their line counts (6 and 2) and no run yet');
ok(($p['unknown_plus'] ?? []) === [['plu' => '2002', 'name' => 'SMOKE Mystery Special']], 'the unknown PLU 2002 listed with its name (1001 and 3001 are mapped)');
ok(($p['bad_count'] ?? 0) === 1 && trim((string) ($p['bad'][0]['reason'] ?? '')) !== '', 'the malformed row with its reason: ' . json_encode($p['bad'][0] ?? null));
ok((int) one('SELECT count(*) FROM source_pulls WHERE source_id = :s', ['s' => $toast]) === 0 && (int) one('SELECT count(*) FROM pos_sales') === 0, 'NOTHING written: no pull row, no check');
$r = post_file($bea, '/sales/upload', ['source' => (string) $toast, 'preview' => 'yes'], 'file', $TOAST, null, ['HX-Request: true']);
ok($r['code'] === 200 && has($r, 'id="upload-preview-table"') && has($r, 'id="upload-preview-unknown"') && has($r, '2002') && has($r, 'id="upload-preview-bad"') && !has($r, '<html'), 'the HTMX preview partial: the table, the new PLU it will create, the bad row');
ok(has(page($bea, '/sales/upload'), 'id="upload-import-btn"'), "Import is the page's own button (fixed at the bottom on a phone)");
$r = post_file($bea, '/sales/upload', ['source' => (string) $toast, 'preview' => 'yes'], 'file', $TOAST);
ok($r['code'] === 200 && has($r, 'id="upload-form"') && has($r, 'id="upload-preview-card"'), 'JavaScript off: the screen again with the preview under the form');

echo "3. Import\n";
$r = post_file_json($bea, '/sales/upload', ['source' => (string) $toast, 'deplete' => 'yes'], 'file', $TOAST);
$j = $r['json'];
ok($r['code'] === 200 && ($j['ok'] ?? false) === true && ($j['dates_seen'] ?? []) === [D1, D2], 'imported: the two dates seen');
ok(($j['sales_new'] ?? -1) === 5 && ($j['lines_seen'] ?? -1) === 8 && ($j['plus_new'] ?? -1) === 1 && ($j['bad_rows'] ?? -1) === 1, 'sales_new 5, lines_seen 8, plus_new 1, one bad row');
ok(($j['status'] ?? '') === 'partial' && count($j['runs'] ?? []) === 2 && ($j['runs'][0]['business_date'] ?? '') === D1 && isset($j['runs'][1]['run_id']), 'status partial (the bad row); two runs posted, day 1 first');
foreach (['dates_seen', 'sales_new', 'lines_seen', 'plus_new', 'runs', 'pull_id', 'record_id'] as $k) { $miss[] = array_key_exists($k, $j) ? null : $k; }
ok(array_filter($miss) === [], 'JSON mode: {dates_seen, sales_new, lines_seen, plus_new, runs[], pull_id, record_id}');
$pull = q('SELECT * FROM source_pulls WHERE id = :p', ['p' => (int) $j['pull_id']])[0] ?? [];
ok(($pull['kind'] ?? '') === 'upload' && $pull['status'] === 'partial' && $pull['file_name'] === 'toast_items.csv' && (int) $pull['started_by'] === 28 && (int) $pull['sales_new'] === 5 && $pull['finished_at'] !== null, 'the pull row: upload, partial, the file name, Bea, the counts');
$att = q('SELECT * FROM attachments WHERE id = :a', ['a' => (int) $pull['attachment_id']])[0] ?? [];
ok(($att['record_type'] ?? '') === 'source' && (int) $att['record_id'] === $toast && $att['filename'] === 'toast_items.csv' && $att['sha256'] === hash_file('sha256', $TOAST), "the file kept: an attachment on the source, named on the pull, its bytes' hash");
$log = activity('sale.import', $since);
$a = json_decode($log[0]['after'] ?? '{}', true);
ok(count($log) === 1 && (int) $log[0]['scope_id'] === DOWNTOWN && $a['sales_new'] === 5 && $a['lines_seen'] === 8 && !str_contains($log[0]['after'], 'Chicken'), 'sale.import logged with the site and counts only');
ok(count(activity('depletion.run', $since)) === 2, 'depletion.run logged twice');
ok((int) one("SELECT count(*) FROM notifications WHERE member_id = 27 AND kind = 'unmapped'") === 1, "the Manager (Marco) told once that a PLU waits to be mapped");
$r = post_file($bea, '/sales/upload', ['source' => (string) $toast], 'file', $TOAST);
ok(in_array($r['code'], [302, 303], true) && preg_match('#Location: (/sales/\?[^\r\n]+)#i', $r['headers'], $m) === 1 && str_contains(urldecode($m[1]), 'highlight=' . D1 . ',' . D2), 'the form post lands on the day list with the dates highlighted');
$r = page($bea, trim($m[1] ?? '/sales/'));
ok($r['code'] === 200 && has($r, 'id="sales-day-list-content"') && has($r, 'id="day-row-' . D1 . '"') && has($r, 'Imported 2 days'), 'the day list shows the days and the notice');

echo "4. Again — idempotent\n";
$r = post_file_json($bea, '/sales/upload', ['source' => (string) $toast], 'file', $TOAST);
ok($r['code'] === 200 && ($r['json']['sales_new'] ?? -1) === 0 && ($r['json']['sales_changed'] ?? -1) === 0 && ($r['json']['runs'] ?? [1]) === [], 'the same file again (the redirect above was the second): sales_new 0, nothing changed, no run');
ok((int) one('SELECT count(*) FROM pos_sales WHERE source_id = :s', ['s' => $toast]) === 5 && (int) one('SELECT count(*) FROM pos_sale_lines l JOIN pos_sales s ON s.id = l.sale_id WHERE s.source_id = :s', ['s' => $toast]) === 8, 'still five checks and eight lines');
ok((int) one("SELECT count(*) FROM depletion_runs WHERE scope_id = 101") === 2 && !is_due(D1) && !is_due(D2), 'still two runs; neither day due');
$rows = array_map('str_getcsv', file($TOAST, FILE_IGNORE_NEW_LINES));
$xlsx = $tmp . '/toast_items.xlsx';
RiPosXlsx::write($xlsx, $rows);
$r = post_file_json($bea, '/sales/upload', ['source' => (string) $toast], 'file', $xlsx);
ok($r['code'] === 200 && ($r['json']['lines_seen'] ?? 0) === 8 && ($r['json']['sales_new'] ?? -1) === 0 && ($r['json']['dates_seen'] ?? []) === [D1, D2] && ($r['json']['bad_rows'] ?? 0) === 1, 'an XLSX of the same rows: the same counts — eight lines, two dates, nothing new');
$r = post_file_json($bea, '/sales/upload', ['source' => (string) $toast, 'preview' => 'yes'], 'file', $TOAST);
ok(($r['json']['preview']['dates'][0]['run'] ?? '') === 'partial' && ($r['json']['preview']['dates'][0]['run_no'] ?? 0) === 1 && ($r['json']['preview']['unknown_plus'] ?? [1]) === [], "a preview now: day 1's run shown (partial, run 1); no PLU left to create (2002 exists, unmapped, in the queue)");

echo "5. Refusals\n";
$pulls = (int) one('SELECT count(*) FROM source_pulls');
$r = post_file_json($bea, '/sales/upload', ['source' => (string) $toast, 'mapping' => 'clover_items'], 'file', FIX . '/generic.csv');
ok($r['code'] === 422 && str_contains($r['json']['error']['message'] ?? '', 'lacks the column') && ($r['json']['error']['code'] ?? '') !== '', 'a file the mapping cannot read → 422 with the reason');
ok((string) one("SELECT status FROM source_pulls WHERE source_id = :s ORDER BY id DESC LIMIT 1", ['s' => $toast]) === 'failed' && str_contains((string) one("SELECT error FROM source_pulls WHERE source_id = :s ORDER BY id DESC LIMIT 1", ['s' => $toast]), 'lacks'), 'its pull row failed with the reason');
ok((int) one('SELECT consecutive_failures FROM sources WHERE id = :s', ['s' => $toast]) === 1, 'the source counts one failure');
$r = post_file_json($bea, '/sales/upload', ['source' => (string) $toast], 'file', $TOAST);
ok((int) one('SELECT consecutive_failures FROM sources WHERE id = :s', ['s' => $toast]) === 0 && one('SELECT backoff_until FROM sources WHERE id = :s', ['s' => $toast]) === null, 'the next good file clears the failures');
$r = post_file_json($bea, '/sales/upload', ['source' => (string) $square], 'file', $TOAST);
ok($r['code'] === 422 && str_contains($r['json']['error']['message'] ?? '', 'fed by its API'), 'an upload to the Square source → 422 "fed by its API"');
post_json($admin, '/sales/sources/pause.php', ['source' => (string) $toast, 'paused' => 'yes', 'reason' => 'SMOKE']);
$r = post_file_json($bea, '/sales/upload', ['source' => (string) $toast], 'file', $TOAST);
ok($r['code'] === 422 && str_contains($r['json']['error']['message'] ?? '', 'is paused'), 'a paused source → 422 "paused — resume it first"');
post_json($admin, '/sales/sources/pause.php', ['source' => (string) $toast, 'paused' => 'no']);
$r = post_json($bea, '/sales/upload', ['source' => (string) $toast]);
ok($r['code'] === 422 && isset($r['json']['error']['fields']['file']) && ($r['json']['error']['code'] ?? '') === 'invalid', 'no file → 422 {error: {code: invalid, fields: {file}}}');
$pdf = $tmp . '/sales.pdf'; file_put_contents($pdf, '%PDF-1.4');
ok(post_file_json($bea, '/sales/upload', ['source' => (string) $toast], 'file', $pdf)['code'] === 422, 'a PDF → 422');
ok(post_file_json($ann, '/sales/upload', ['source' => (string) $toast], 'file', $TOAST)['code'] === 403, 'Ann → 403');
ok(post_file_json($bea, '/sales/upload', ['source' => 'new', 'mapping' => 'generic'], 'file', FIX . '/generic.csv')['code'] === 403, "Bea cannot make a new source from the upload (settings.manage)");
ok(post_file_json($bea, '/sales/upload', ['source' => '999999'], 'file', $TOAST)['code'] === 404, 'an unknown source → 404');
ok((int) one('SELECT count(*) FROM source_pulls') === $pulls + 2, 'the refusals before reading the file wrote no pull (two pulls: the failed one and the good one)');
$r = post_file_json($marco, '/sales/upload', ['source' => 'SMOKE Toast export'], 'file', $TOAST);
ok($r['code'] === 200 && ($r['json']['sales_new'] ?? -1) === 0, 'Marco uploads naming the source by its name (the resolver shape)');

echo "6. Resolution and day parts\n";
ok((int) one('SELECT count(*) FROM pos_sale_lines l JOIN pos_sales s ON s.id = l.sale_id WHERE s.source_id = :s AND l.menu_item_id IS NULL', ['s' => $toast]) === 0, "every line's menu_item_id set");
$mi = q("SELECT * FROM menu_items WHERE pos_source_id = :s AND plu = '2002'", ['s' => $toast])[0] ?? [];
ok(($mi['name'] ?? '') === 'SMOKE Mystery Special' && (float) $mi['sale_price'] === 16.0 && $mi['recipe_id'] === null, 'PLU 2002 created unmapped with the line\'s name and price');
$pq = activity('plu.queue', $since);
ok(count($pq) === 1 && (int) $pq[0]['entity_id'] === (int) $mi['id'] && (int) $pq[0]['scope_id'] === DOWNTOWN, 'plu.queue logged once');
$dp = static fn (string $x): ?string => one("SELECT d.name FROM pos_sales s LEFT JOIN day_parts d ON d.id = s.day_part_id WHERE s.source_id = :s AND s.external_id = :x", ['s' => $toast, 'x' => $x]) ?: null;
ok($dp('SMK-001') === 'Lunch' && $dp('SMK-004') === 'Lunch', 'closed 12:30 and 13:05 local → Lunch');
ok($dp('SMK-002') === 'Dinner' && $dp('SMK-005') === 'Dinner', 'closed 19:10 and 20:40 → Dinner');
ok($dp('SMK-003') === null, 'closed 03:30 → no day part (before the cut, outside every part — DECISION)');
$s3 = q("SELECT business_date::text AS bd, to_char(closed_at AT TIME ZONE 'America/New_York', 'YYYY-MM-DD HH24:MI') AS local FROM pos_sales WHERE source_id = :s AND external_id = 'SMK-003'", ['s' => $toast])[0];
ok($s3['bd'] === D1 && $s3['local'] === '2026-10-06 03:30', "SMK-003 closed 2026-10-06 03:30 local belongs to the file's business date 2026-10-05");
$l1 = q("SELECT l.qty, l.voided, l.comp, l.modifiers, l.line_total FROM pos_sale_lines l JOIN pos_sales s ON s.id = l.sale_id WHERE s.source_id = :s AND s.external_id = 'SMK-002' ORDER BY l.id", ['s' => $toast]);
ok(count($l1) === 3 && $l1[0]['voided'] === true && $l1[1]['comp'] === true && json_decode($l1[1]['modifiers'], true)[0]['code'] === 'NOTOM', 'SMK-002: the void, the comp with NOTOM, the unknown PLU');
$m4 = json_decode((string) one("SELECT l.modifiers FROM pos_sale_lines l JOIN pos_sales s ON s.id = l.sale_id WHERE s.source_id = :s AND s.external_id = 'SMK-004'", ['s' => $toast]), true);
ok(array_map(static fn ($m) => $m['code'] . 'x' . (float) $m['qty'], $m4) === ['XCHKx2', 'NOTOMx1'], 'SMK-004: XCHK ×2 and NOTOM read from Toast\'s modifier list');
$s1 = q("SELECT subtotal, covers, comps, voids FROM pos_sales WHERE source_id = :s AND external_id = 'SMK-001'", ['s' => $toast])[0];
ok((float) $s1['subtotal'] === 39.0 && (int) $s1['covers'] === 2, 'SMK-001: subtotal 39.00, two covers');

echo "7. Airport: a new upload source, the modifiers seen first, no storage area\n";
$airAdmin = at(1, AIRPORT);
$r = post_file_json($airAdmin, '/sales/upload', ['source' => 'new', 'mapping' => 'generic', 'deplete' => 'yes'], 'file', FIX . '/generic.csv');
$air = (int) one("SELECT id FROM sources WHERE scope_id = 102 AND name = 'POS uploads'");
ok($r['code'] === 200 && $air > 0 && ($r['json']['plus_new'] ?? 0) === 3 && ($r['json']['sales_new'] ?? 0) === 5 && activity('source.create', $since) !== [], "the admin's \"new\" makes \"POS uploads\" at Airport (file, generic, logged) and imports: three PLUs new");
ok((int) one("SELECT count(*) FROM modifiers WHERE pos_source_id = :s AND code IN ('XCHK', 'NOTOM') AND recipe_id IS NULL", ['s' => $air]) === 2, 'XCHK and NOTOM upserted on first sight, unmapped');
$runs = $r['json']['runs'] ?? [];
ok(count($runs) === 2 && $runs[0]['status'] === 'partial' && $runs[0]['lines_depleted'] === 0 && $runs[0]['lines_unmapped'] === 5 && $runs[0]['ingredients'] === 0, 'a day of unmapped PLUs only: a partial run, nothing depleted, five unmapped (the void apart)');
$s3 = q("SELECT to_char(closed_at AT TIME ZONE 'America/Chicago', 'HH24:MI') AS t FROM pos_sales WHERE source_id = :s AND external_id = 'SMK-001'", ['s' => $air])[0];
ok($s3['t'] === '12:30', "Airport's times read in its own zone (America/Chicago)");
map_source($air);
ri_sql("UPDATE pos_sales SET imported_at = now() WHERE source_id = :s AND business_date = :d", ['s' => $air, 'd' => D1]);
ok(is_due(D1, AIRPORT), 'mapped (slice 2 touches imported_at): Airport day 1 due again');
$r = post_json($airAdmin, '/sales/runs/run.php', ['business_date' => D1]);
ok($r['code'] === 422 && str_contains($r['json']['error']['message'] ?? '', 'no storage area'), "a site with no storage area: 422 in the function's sentence");
ok(is_due(D1, AIRPORT) && (string) one("SELECT status FROM depletion_runs WHERE scope_id = 102 AND business_date = :d ORDER BY id DESC LIMIT 1", ['d' => D1]) === 'partial', 'the day left due, the old run untouched (the refusal rolled back its void)');
$r = page($admin, '/sales/sources/');
ok(!has($r, 'id="source-card-' . $air . '"'), "Downtown's list does not hold Airport's source (signed on at Downtown)");
$c = page(at(29, DOWNTOWN), '/sales/sources/' . $air)['code'];
ok(in_array($c, [403, 404], true), "Ann (Downtown only) cannot open Airport's source ($c)");
finish();
